def fetch_page(page):
    pages = {1: {'data': [1, 2], 'next_page': 2}, 2: {'data': [3], 'next_page': 3}, 3: {'data': [4, 5], 'next_page': None}}
    return pages[page]

def fetch_all():
    out, page = [], 1
    while page is not None:
        resp = fetch_page(page)
        out.extend(resp['data'])
        page = resp['next_page']
    return out

